#!/usr/bin/env python3
from __future__ import annotations

from pathlib import Path


def replace_once(text: str, old: str, new: str, label: str) -> str:
    if old not in text:
        raise RuntimeError(f"missing patch anchor: {label}")
    if text.count(old) != 1:
        raise RuntimeError(f"ambiguous patch anchor: {label}")
    return text.replace(old, new, 1)


def patch_dump() -> None:
    path = Path("tools/tsun_dump.py")
    text = path.read_text(encoding="utf-8")

    text = replace_once(
        text,
        "import math\nfrom pathlib import Path\nimport re\nimport socket\nimport sys\nimport time\nfrom typing import Any, Callable, Iterable\nfrom urllib.parse import urljoin, urlsplit\n",
        "import math\nimport os\nfrom pathlib import Path\nimport re\nimport socket\nimport sys\nimport time\nfrom typing import Any, Callable, Iterable\nfrom urllib.parse import urljoin, urlsplit\nimport urllib.request\n",
        "dump imports",
    )
    text = replace_once(text, 'TOOL_VERSION = "2.6.0"', 'TOOL_VERSION = "2.7.0"', "dump version")
    text = replace_once(
        text,
        'REPORT_EMAIL = "dev@jptstar.com"\n\nDEFAULT_PORT = 8899\n',
        '''REPORT_EMAIL = "dev@jptstar.com"\n\nUPDATE_RELEASE_BASE = (\n    "https://github.com/jptstar/tsun-local/releases/download/diagnostic-latest"\n)\nUPDATE_MANIFEST_URL = f"{UPDATE_RELEASE_BASE}/update.json"\nUPDATE_TIMEOUT = 3.0\nUPDATE_MAX_MANIFEST_BYTES = 64 * 1024\nUPDATE_MAX_ASSET_BYTES = 150 * 1024 * 1024\nUPDATE_COMPONENT_DUMP = "dump"\nUPDATE_COMPONENT_WINDOWS_GUI = "windows_gui"\n\nDEFAULT_PORT = 8899\n''',
        "update constants",
    )

    anchor = '''class TsunProtocolError(Exception):\n    """Raised when a TSUN protocol frame is invalid."""\n\n\n@dataclass(slots=True)\nclass DiscoveryDevice:\n'''
    replacement = '''class TsunProtocolError(Exception):\n    """Raised when a TSUN protocol frame is invalid."""\n\n\nclass TsunUpdateError(Exception):\n    """Raised when a diagnostic self-update cannot be validated safely."""\n\n\ndef _version_key(value: str) -> tuple[int, int, int, int]:\n    """Return a comparable numeric key for the diagnostic release versions."""\n    core = value.strip().split("+", 1)[0].split("-", 1)[0]\n    parts = core.split(".")\n    if not 1 <= len(parts) <= 4 or any(not part.isdigit() for part in parts):\n        raise TsunUpdateError(f"Invalid update version: {value!r}")\n    numbers = [int(part) for part in parts]\n    numbers.extend([0] * (4 - len(numbers)))\n    return tuple(numbers)  # type: ignore[return-value]\n\n\ndef _download_bytes(url: str, *, timeout: float, max_bytes: int) -> bytes:\n    """Download one bounded HTTPS resource from the public diagnostic release."""\n    if not url.startswith("https://github.com/"):\n        raise TsunUpdateError("Update URL is not an approved GitHub HTTPS URL")\n    request = urllib.request.Request(\n        url,\n        headers={"User-Agent": f"TSUN-Local-Diagnostic/{TOOL_VERSION}"},\n    )\n    with urllib.request.urlopen(request, timeout=timeout) as response:\n        data = response.read(max_bytes + 1)\n    if len(data) > max_bytes:\n        raise TsunUpdateError("Update download exceeds the allowed size")\n    return data\n\n\ndef fetch_update_manifest(timeout: float = UPDATE_TIMEOUT) -> dict[str, Any]:\n    """Fetch and validate the rolling diagnostic release manifest."""\n    raw = _download_bytes(\n        UPDATE_MANIFEST_URL, timeout=timeout, max_bytes=UPDATE_MAX_MANIFEST_BYTES\n    )\n    try:\n        manifest = json.loads(raw.decode("utf-8"))\n    except (UnicodeDecodeError, json.JSONDecodeError) as err:\n        raise TsunUpdateError("Invalid diagnostic update manifest") from err\n    if not isinstance(manifest, dict) or manifest.get("schema_version") != 1:\n        raise TsunUpdateError("Unsupported diagnostic update manifest")\n    if not isinstance(manifest.get("components"), dict):\n        raise TsunUpdateError("Diagnostic update manifest has no components")\n    return manifest\n\n\ndef select_update_component(\n    manifest: dict[str, Any], component: str, current_version: str\n) -> dict[str, str] | None:\n    """Return one newer validated component description, or None when current."""\n    components = manifest.get("components")\n    if not isinstance(components, dict):\n        raise TsunUpdateError("Diagnostic update manifest has no components")\n    candidate = components.get(component)\n    if not isinstance(candidate, dict):\n        raise TsunUpdateError(f"Diagnostic update component {component!r} is missing")\n\n    version = candidate.get("version")\n    asset = candidate.get("asset")\n    sha256 = candidate.get("sha256")\n    if not isinstance(version, str) or not isinstance(asset, str) or not isinstance(sha256, str):\n        raise TsunUpdateError("Diagnostic update component metadata is incomplete")\n    if Path(asset).name != asset or not re.fullmatch(r"[A-Za-z0-9._-]+", asset):\n        raise TsunUpdateError("Unsafe diagnostic update asset name")\n    if not re.fullmatch(r"[0-9a-fA-F]{64}", sha256):\n        raise TsunUpdateError("Invalid diagnostic update SHA-256")\n    if _version_key(version) <= _version_key(current_version):\n        return None\n    return {\n        "component": component,\n        "version": version,\n        "asset": asset,\n        "sha256": sha256.lower(),\n        "build_commit": str(manifest.get("build_commit") or ""),\n    }\n\n\ndef check_for_update(\n    component: str, current_version: str, *, timeout: float = UPDATE_TIMEOUT\n) -> dict[str, str] | None:\n    """Check the rolling release and return a newer component when available."""\n    return select_update_component(\n        fetch_update_manifest(timeout=timeout), component, current_version\n    )\n\n\ndef download_verified_update(\n    update: dict[str, str], destination: Path, *, timeout: float = UPDATE_TIMEOUT\n) -> Path:\n    """Download one release asset and write it only after SHA-256 verification."""\n    asset = update["asset"]\n    expected = update["sha256"].lower()\n    payload = _download_bytes(\n        f"{UPDATE_RELEASE_BASE}/{asset}",\n        timeout=timeout,\n        max_bytes=UPDATE_MAX_ASSET_BYTES,\n    )\n    actual = hashlib.sha256(payload).hexdigest()\n    if actual != expected:\n        raise TsunUpdateError(\n            f"SHA-256 mismatch for {asset}: expected {expected}, got {actual}"\n        )\n\n    destination = Path(destination)\n    destination.parent.mkdir(parents=True, exist_ok=True)\n    staged = destination.with_name(f".{destination.name}.download-{os.getpid()}")\n    try:\n        staged.write_bytes(payload)\n        os.replace(staged, destination)\n    finally:\n        try:\n            staged.unlink()\n        except FileNotFoundError:\n            pass\n    return destination\n\n\ndef update_python_script_if_available(\n    *, timeout: float = UPDATE_TIMEOUT\n) -> dict[str, str]:\n    """Atomically replace this standalone .py when a newer verified release exists."""\n    if getattr(sys, "frozen", False):\n        return {"status": "not_applicable", "version": TOOL_VERSION}\n\n    update = check_for_update(UPDATE_COMPONENT_DUMP, TOOL_VERSION, timeout=timeout)\n    if update is None:\n        return {"status": "up_to_date", "version": TOOL_VERSION}\n\n    target = Path(__file__).resolve()\n    try:\n        mode = target.stat().st_mode\n    except OSError as err:\n        raise TsunUpdateError(f"Cannot inspect current script: {err}") from err\n\n    staged = target.with_name(f".{target.name}.update-{os.getpid()}")\n    try:\n        download_verified_update(update, staged, timeout=timeout)\n        os.replace(staged, target)\n        try:\n            os.chmod(target, mode)\n        except OSError:\n            pass\n    except OSError as err:\n        raise TsunUpdateError(\n            "A newer diagnostic script is available, but the current file cannot "\n            "be replaced automatically"\n        ) from err\n    finally:\n        try:\n            staged.unlink()\n        except FileNotFoundError:\n            pass\n\n    return {\n        "status": "updated",\n        "version": update["version"],\n        "target": str(target),\n    }\n\n\n@dataclass(slots=True)\nclass DiscoveryDevice:\n'''
    text = replace_once(text, anchor, replacement, "update helpers")

    parser_anchor = '''    parser.add_argument(\n        "--compare",\n        nargs=2,\n        metavar=("BEFORE_JSON", "AFTER_JSON"),\n        help="compare two existing dump files without connecting to an inverter",\n    )\n    return parser\n'''
    parser_replacement = '''    parser.add_argument(\n        "--compare",\n        nargs=2,\n        metavar=("BEFORE_JSON", "AFTER_JSON"),\n        help="compare two existing dump files without connecting to an inverter",\n    )\n    parser.add_argument(\n        "--no-update",\n        action="store_true",\n        help="skip the automatic diagnostic-tool update check for this run",\n    )\n    parser.add_argument(\n        "--check-update",\n        action="store_true",\n        help="check diagnostic-latest for a newer tsun_dump.py and exit",\n    )\n    return parser\n'''
    text = replace_once(text, parser_anchor, parser_replacement, "update CLI options")

    main_anchor = '''    args = build_parser().parse_args()\n\n    if args.compare:\n'''
    main_replacement = '''    args = build_parser().parse_args()\n\n    if args.check_update:\n        try:\n            update = check_for_update(UPDATE_COMPONENT_DUMP, TOOL_VERSION)\n        except Exception as err:\n            print(f"Update check failed: {type(err).__name__}: {err}", file=sys.stderr)\n            return 1\n        if update is None:\n            print(f"tsun_dump.py v{TOOL_VERSION} is up to date.")\n        else:\n            print(\n                f"tsun_dump.py v{update['version']} is available "\n                f"(current v{TOOL_VERSION})."\n            )\n        return 0\n\n    if not args.no_update and not getattr(sys, "frozen", False):\n        try:\n            update_result = update_python_script_if_available()\n        except Exception as err:\n            print(\n                f"Update check unavailable; continuing with v{TOOL_VERSION}: "\n                f"{type(err).__name__}: {err}",\n                file=sys.stderr,\n            )\n        else:\n            if update_result.get("status") == "updated":\n                print(\n                    f"Updated tsun_dump.py to v{update_result['version']}; restarting..."\n                )\n                target = update_result.get("target", str(Path(__file__).resolve()))\n                os.execv(\n                    sys.executable,\n                    [sys.executable, target, *sys.argv[1:]],\n                )\n\n    if args.compare:\n'''
    text = replace_once(text, main_anchor, main_replacement, "update startup")
    path.write_text(text, encoding="utf-8")


def patch_gui() -> None:
    path = Path("tools/tsun_diagnostic_gui.py")
    text = path.read_text(encoding="utf-8")
    text = replace_once(
        text,
        "import os\nfrom pathlib import Path\nimport queue\nimport sys\nimport threading\nimport tkinter as tk\n",
        "import os\nfrom pathlib import Path\nimport queue\nimport shutil\nimport subprocess\nimport sys\nimport tempfile\nimport threading\nimport time\nimport tkinter as tk\n",
        "gui imports",
    )
    text = replace_once(text, 'APP_VERSION = "1.3.0"', 'APP_VERSION = "1.4.0"', "gui version")

    language_anchor = '''def _language() -> str:\n    try:\n        current = (locale.getlocale()[0] or "").lower()\n    except (ValueError, TypeError):\n        current = ""\n    return "fr" if current.startswith("fr") else "en"\n\n\nclass _QueueWriter(io.TextIOBase):\n'''
    language_replacement = '''def _language() -> str:\n    try:\n        current = (locale.getlocale()[0] or "").lower()\n    except (ValueError, TypeError):\n        current = ""\n    return "fr" if current.startswith("fr") else "en"\n\n\n_INTERNAL_UPDATE_SWITCH = "--apply-update"\n\n\ndef _run_downloaded_windows_updater(target: Path) -> int:\n    """Replace the old portable EXE after its process releases the file lock."""\n    if os.name != "nt" or not getattr(sys, "frozen", False):\n        return 2\n    if target.name.lower() != "tsun-local-diagnostic.exe":\n        return 2\n\n    source = Path(sys.executable).resolve()\n    deadline = time.monotonic() + 20.0\n    last_error: OSError | None = None\n    while time.monotonic() < deadline:\n        try:\n            shutil.copy2(source, target)\n        except OSError as err:\n            last_error = err\n            time.sleep(0.25)\n            continue\n        try:\n            subprocess.Popen([str(target), "--no-update"], close_fds=True)\n        except OSError:\n            return 1\n        return 0\n    if last_error is not None:\n        return 1\n    return 1\n\n\ndef _internal_update_mode() -> int | None:\n    """Handle the hidden helper mode used by the newly downloaded EXE."""\n    if len(sys.argv) >= 3 and sys.argv[1] == _INTERNAL_UPDATE_SWITCH:\n        return _run_downloaded_windows_updater(Path(sys.argv[2]).resolve())\n    return None\n\n\ndef _maybe_auto_update_windows() -> bool:\n    """Download, verify and hand off to a newer portable Windows executable."""\n    if (\n        os.name != "nt"\n        or not getattr(sys, "frozen", False)\n        or "--no-update" in sys.argv\n    ):\n        return False\n    try:\n        update = tsun_dump.check_for_update(\n            tsun_dump.UPDATE_COMPONENT_WINDOWS_GUI,\n            APP_VERSION,\n        )\n        if update is None:\n            return False\n        destination = Path(tempfile.gettempdir()) / (\n            f"TSUN-Local-Diagnostic-update-{update['version']}-{os.getpid()}.exe"\n        )\n        tsun_dump.download_verified_update(update, destination)\n        creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0)\n        subprocess.Popen(\n            [\n                str(destination),\n                _INTERNAL_UPDATE_SWITCH,\n                str(Path(sys.executable).resolve()),\n            ],\n            close_fds=True,\n            creationflags=creationflags,\n        )\n        return True\n    except Exception:\n        # Updating must never prevent the currently installed diagnostic from running.\n        return False\n\n\nclass _QueueWriter(io.TextIOBase):\n'''
    text = replace_once(text, language_anchor, language_replacement, "gui updater helpers")

    main_anchor = '''def main() -> int:\n    root = tk.Tk()\n    DiagnosticApp(root)\n    root.mainloop()\n    return 0\n'''
    main_replacement = '''def main() -> int:\n    internal_result = _internal_update_mode()\n    if internal_result is not None:\n        return internal_result\n    if _maybe_auto_update_windows():\n        return 0\n\n    root = tk.Tk()\n    DiagnosticApp(root)\n    root.mainloop()\n    return 0\n'''
    text = replace_once(text, main_anchor, main_replacement, "gui main updater hook")
    path.write_text(text, encoding="utf-8")


def patch_existing_tests() -> None:
    path = Path("tests/test_tsun_dump_tool.py")
    text = path.read_text(encoding="utf-8")
    text = replace_once(text, 'self.assertEqual(TOOL.TOOL_VERSION, "2.6.0")', 'self.assertEqual(TOOL.TOOL_VERSION, "2.7.0")', "dump test version")
    path.write_text(text, encoding="utf-8")


def write_update_tests() -> None:
    Path("tests/test_diagnostic_updates.py").write_text(
        '''from __future__ import annotations\n\nimport hashlib\nimport importlib.util\nfrom pathlib import Path\nimport sys\nimport tempfile\nimport unittest\nfrom unittest.mock import patch\n\n\nTOOL_PATH = Path(__file__).parents[1] / "tools" / "tsun_dump.py"\nSPEC = importlib.util.spec_from_file_location("tsun_dump_update_test", TOOL_PATH)\nassert SPEC is not None and SPEC.loader is not None\nTOOL = importlib.util.module_from_spec(SPEC)\nsys.modules[SPEC.name] = TOOL\nSPEC.loader.exec_module(TOOL)\n\n\nclass DiagnosticUpdateTests(unittest.TestCase):\n    def _manifest(self, *, version: str = "9.0.0", asset: str = "tsun_dump.py", payload: bytes = b"new") -> dict:\n        return {\n            "schema_version": 1,\n            "build_commit": "abc123",\n            "components": {\n                "dump": {\n                    "version": version,\n                    "asset": asset,\n                    "sha256": hashlib.sha256(payload).hexdigest(),\n                }\n            },\n        }\n\n    def test_version_comparison_is_numeric(self) -> None:\n        self.assertGreater(TOOL._version_key("2.10.0"), TOOL._version_key("2.9.9"))\n        self.assertEqual(TOOL._version_key("2.7"), (2, 7, 0, 0))\n\n    def test_selects_only_a_newer_component(self) -> None:\n        manifest = self._manifest(version="2.8.0")\n        update = TOOL.select_update_component(manifest, "dump", "2.7.0")\n        self.assertIsNotNone(update)\n        assert update is not None\n        self.assertEqual(update["version"], "2.8.0")\n        self.assertIsNone(TOOL.select_update_component(manifest, "dump", "2.8.0"))\n        self.assertIsNone(TOOL.select_update_component(manifest, "dump", "2.9.0"))\n\n    def test_rejects_unsafe_asset_names(self) -> None:\n        manifest = self._manifest(asset="../tsun_dump.py")\n        with self.assertRaises(TOOL.TsunUpdateError):\n            TOOL.select_update_component(manifest, "dump", "2.7.0")\n\n    def test_download_is_written_only_after_hash_validation(self) -> None:\n        payload = b"verified update payload"\n        manifest = self._manifest(payload=payload)\n        update = TOOL.select_update_component(manifest, "dump", "2.7.0")\n        assert update is not None\n        with tempfile.TemporaryDirectory() as directory:\n            destination = Path(directory) / "tsun_dump.py"\n            with patch.object(TOOL, "_download_bytes", return_value=payload):\n                TOOL.download_verified_update(update, destination)\n            self.assertEqual(destination.read_bytes(), payload)\n\n    def test_hash_mismatch_does_not_replace_destination(self) -> None:\n        expected = b"expected"\n        actual = b"tampered"\n        manifest = self._manifest(payload=expected)\n        update = TOOL.select_update_component(manifest, "dump", "2.7.0")\n        assert update is not None\n        with tempfile.TemporaryDirectory() as directory:\n            destination = Path(directory) / "tsun_dump.py"\n            destination.write_bytes(b"old")\n            with patch.object(TOOL, "_download_bytes", return_value=actual):\n                with self.assertRaises(TOOL.TsunUpdateError):\n                    TOOL.download_verified_update(update, destination)\n            self.assertEqual(destination.read_bytes(), b"old")\n\n    def test_cli_exposes_update_controls(self) -> None:\n        parser = TOOL.build_parser()\n        self.assertTrue(parser.parse_args(["--no-update"]).no_update)\n        self.assertTrue(parser.parse_args(["--check-update"]).check_update)\n\n\nif __name__ == "__main__":\n    unittest.main()\n''',
        encoding="utf-8",
    )


def write_workflow() -> None:
    Path(".github/workflows/build-diagnostic-exe.yml").write_text(
        '''name: Build Windows diagnostic executable\n\non:\n  workflow_dispatch:\n  pull_request:\n    paths:\n      - "tools/tsun_dump.py"\n      - "tools/tsun_diagnostic_gui.py"\n      - ".github/workflows/build-diagnostic-exe.yml"\n  push:\n    branches:\n      - main\n    paths:\n      - "tools/tsun_dump.py"\n      - "tools/tsun_diagnostic_gui.py"\n      - ".github/workflows/build-diagnostic-exe.yml"\n\npermissions:\n  contents: write\n\nconcurrency:\n  group: windows-diagnostic-${{ github.ref }}\n  cancel-in-progress: true\n\njobs:\n  build:\n    runs-on: windows-latest\n\n    steps:\n      - name: Check out repository\n        uses: actions/checkout@v4\n\n      - name: Set up Python\n        uses: actions/setup-python@v5\n        with:\n          python-version: "3.12"\n\n      - name: Install PyInstaller\n        shell: pwsh\n        run: python -m pip install --disable-pip-version-check pyinstaller\n\n      - name: Validate sources\n        shell: pwsh\n        run: |\n          python -m py_compile tools/tsun_dump.py tools/tsun_diagnostic_gui.py\n          python -c "import sys; sys.path.insert(0, 'tools'); import tsun_dump, tsun_diagnostic_gui; assert hasattr(tsun_dump, 'main'); print('tsun_dump', tsun_dump.TOOL_VERSION, 'GUI', tsun_diagnostic_gui.APP_VERSION)"\n\n      - name: Build portable executable\n        shell: pwsh\n        run: |\n          python -m PyInstaller --noconfirm --clean --onefile --windowed `\n            --name TSUN-Local-Diagnostic `\n            --paths tools `\n            tools/tsun_diagnostic_gui.py\n\n      - name: Smoke-test executable launch\n        shell: pwsh\n        run: |\n          $exe = (Resolve-Path "dist/TSUN-Local-Diagnostic.exe").Path\n          $process = Start-Process -FilePath $exe -ArgumentList "--no-update" -PassThru\n          Start-Sleep -Seconds 8\n          if ($process.HasExited) {\n            throw "Executable exited unexpectedly during startup smoke test (exit code $($process.ExitCode))"\n          }\n          Stop-Process -Id $process.Id -Force\n          Write-Host "Executable launched successfully and remained running for the smoke-test window."\n\n      - name: Create rolling update assets and manifest\n        shell: pwsh\n        run: |\n          $exe = "dist/TSUN-Local-Diagnostic.exe"\n          $py = "dist/tsun_dump.py"\n          if (!(Test-Path $exe)) { throw "Executable was not created" }\n\n          Copy-Item "tools/tsun_dump.py" $py -Force\n          $exeHash = (Get-FileHash -Algorithm SHA256 $exe).Hash.ToLowerInvariant()\n          $pyHash = (Get-FileHash -Algorithm SHA256 $py).Hash.ToLowerInvariant()\n          "$exeHash  TSUN-Local-Diagnostic.exe" | Set-Content -Encoding ascii "dist/TSUN-Local-Diagnostic.exe.sha256"\n          "$pyHash  tsun_dump.py" | Set-Content -Encoding ascii "dist/tsun_dump.py.sha256"\n\n          $dumpVersion = (python -c "import sys; sys.path.insert(0, 'tools'); import tsun_dump; print(tsun_dump.TOOL_VERSION)").Trim()\n          $guiVersion = (python -c "import sys; sys.path.insert(0, 'tools'); import tsun_diagnostic_gui; print(tsun_diagnostic_gui.APP_VERSION)").Trim()\n          $manifest = [ordered]@{\n            schema_version = 1\n            channel = "diagnostic-latest"\n            build_commit = $env:GITHUB_SHA\n            components = [ordered]@{\n              dump = [ordered]@{\n                version = $dumpVersion\n                asset = "tsun_dump.py"\n                sha256 = $pyHash\n              }\n              windows_gui = [ordered]@{\n                version = $guiVersion\n                asset = "TSUN-Local-Diagnostic.exe"\n                sha256 = $exeHash\n              }\n            }\n          }\n          $manifest | ConvertTo-Json -Depth 6 | Set-Content -Encoding utf8 "dist/update.json"\n          Write-Host "tsun_dump.py $dumpVersion SHA256: $pyHash"\n          Write-Host "Windows GUI $guiVersion SHA256: $exeHash"\n\n      - name: Upload workflow artifact\n        uses: actions/upload-artifact@v4\n        with:\n          name: TSUN-Local-Diagnostic-Windows\n          path: |\n            dist/TSUN-Local-Diagnostic.exe\n            dist/TSUN-Local-Diagnostic.exe.sha256\n            dist/tsun_dump.py\n            dist/tsun_dump.py.sha256\n            dist/update.json\n          if-no-files-found: error\n          retention-days: 30\n\n      - name: Publish dedicated diagnostic release\n        if: github.event_name == 'push' && github.ref == 'refs/heads/main'\n        shell: pwsh\n        env:\n          GH_TOKEN: ${{ github.token }}\n        run: |\n          $tag = "diagnostic-latest"\n\n          git config user.name "github-actions[bot]"\n          git config user.email "41898282+github-actions[bot]@users.noreply.github.com"\n          git tag -f $tag $env:GITHUB_SHA\n          git push --force origin "refs/tags/$tag"\n\n          gh release view $tag --repo "${{ github.repository }}" *> $null\n          if ($LASTEXITCODE -ne 0) {\n            gh release create $tag `\n              --verify-tag `\n              --title "TSUN Local Diagnostic — latest" `\n              --notes "Rolling prerelease for the standalone TSUN Local read-only diagnostic tool. Windows EXE and Python dumper self-update from verified SHA-256 assets on this release." `\n              --prerelease `\n              --repo "${{ github.repository }}"\n          }\n\n          gh release upload $tag `\n            "dist/TSUN-Local-Diagnostic.exe" `\n            "dist/TSUN-Local-Diagnostic.exe.sha256" `\n            "dist/tsun_dump.py" `\n            "dist/tsun_dump.py.sha256" `\n            "dist/update.json" `\n            --clobber `\n            --repo "${{ github.repository }}"\n\n          Write-Host "Published self-updating diagnostic assets to the dedicated $tag release."\n''',
        encoding="utf-8",
    )


def patch_docs() -> None:
    readme = Path("tools/README.md")
    text = readme.read_text(encoding="utf-8")
    text = text.replace(
        "the current GUI is 1.3.0 and uses the 2.5.1 dump engine.",
        "the current GUI is 1.4.0 and uses the 2.7.0 dump engine.",
    )
    windows_anchor = "The executable is currently unsigned, so Windows SmartScreen may display an unknown-publisher warning. The source of the GUI and the complete build workflow are public in this repository.\n"
    windows_extra = windows_anchor + "\nAt startup the portable EXE checks the rolling `diagnostic-latest` manifest. When a newer GUI is available it downloads the replacement EXE, verifies its SHA-256 before replacing anything, restarts automatically, and falls back to the currently installed copy if GitHub is unavailable or validation fails. Launching the EXE with `--no-update` skips that check for troubleshooting.\n"
    text = replace_once(text, windows_anchor, windows_extra, "README Windows auto-update")
    py_anchor = "Run with Python 3.10+:\n\n```bash\npython3 tsun_dump.py --full\n```\n"
    py_extra = py_anchor + "\nStarting with dump engine 2.7.0, the standalone Python file checks the same `diagnostic-latest` manifest on startup, downloads a newer `tsun_dump.py` when available, verifies SHA-256, atomically replaces the current script and restarts. `--no-update` disables the check for one run and `--check-update` only reports availability. If the script location is not writable, the diagnostic continues with the local version and never requests `sudo`.\n"
    text = replace_once(text, py_anchor, py_extra, "README Python auto-update")
    readme.write_text(text, encoding="utf-8")

    docs = Path("docs/HARDWARE_DUMP.md")
    text = docs.read_text(encoding="utf-8")
    text = text.replace(
        "Current standalone diagnostic versions: **dump engine 2.5.1** · **Windows GUI 1.3.0**.",
        "Current standalone diagnostic versions: **dump engine 2.7.0** · **Windows GUI 1.4.0**.",
    )
    marker = "Current standalone diagnostic versions: **dump engine 2.7.0** · **Windows GUI 1.4.0**.\n"
    addition = marker + "\nBoth distributions use the rolling `diagnostic-latest` update manifest. The Windows EXE replaces itself only after validating the published SHA-256 and restarts automatically; the Mac/Linux standalone `tsun_dump.py` does the same for the Python file. Update failures never block a diagnostic, and `--no-update` provides an offline/troubleshooting path.\n"
    text = replace_once(text, marker, addition, "hardware dump auto-update docs")
    docs.write_text(text, encoding="utf-8")


def main() -> None:
    patch_dump()
    patch_gui()
    patch_existing_tests()
    write_update_tests()
    write_workflow()
    patch_docs()


if __name__ == "__main__":
    main()
